entries.commands:
# ===== 创建 VLAN 子接口（PAN-OS）=====
configure
set network interface ethernet {{parent_port}} layer3 units {{sub_if}} tag {{vlan_id}}
set network interface ethernet {{parent_port}} layer3 units {{sub_if}} ip {{vlan_ip}}/{{prefix_len}}
set network interface ethernet {{parent_port}} layer3 units {{sub_if}} comment "{{vlan_desc}}"
set zone {{zone_name}} network layer3 {{sub_if}}
set network virtual-router default interface {{sub_if}}
commit
show interface all

entries.rollback:
# 回退：删除 VLAN 子接口并解除 zone/虚拟路由器引用（引用未解时 delete 会被拒）
configure
delete zone {{zone_name}} network layer3 {{sub_if}}
delete network virtual-router default interface {{sub_if}}
delete network interface ethernet {{parent_port}} layer3 units {{sub_if}}
commit
# 复核（期望无该接口）
show interface all

entries.commands:
# ===== 链路聚合 + Trunk 子接口（PAN-OS）=====
configure
! ---- 1) 创建 AE 聚合口并加入成员口 ----
set network interface ethernet {{member1}} layer2 lacp enable true
set network interface ethernet {{member1}} aggregate-group {{ae_name}}
set network interface ethernet {{member2}} layer2 lacp enable true
set network interface ethernet {{member2}} aggregate-group {{ae_name}}
! ---- 2) 在 AE 上建子接口作为 Trunk（每个 VLAN 一个 tag 子接口）----
set network interface aggregate-ethernet {{ae_name}} layer3 units {{ae_name}}.{{vlan_id}} tag {{vlan_id}}
set network interface aggregate-ethernet {{ae_name}} layer3 units {{ae_name}}.{{vlan_id}} ip {{vlan_ip}}/{{prefix_len}}
set zone trust network layer3 {{ae_name}}.{{vlan_id}}
set network virtual-router default interface {{ae_name}}.{{vlan_id}}
commit
show interface all
show lacp interfaces

entries.rollback:
# 回退：删除 AE 子接口与引用，成员口解除聚合（成员口原配置按变更记录恢复）
configure
delete zone trust network layer3 {{ae_name}}.{{vlan_id}}
delete network virtual-router default interface {{ae_name}}.{{vlan_id}}
delete network interface aggregate-ethernet {{ae_name}} layer3 units {{ae_name}}.{{vlan_id}}
delete network interface ethernet {{member1}} aggregate-group
delete network interface ethernet {{member1}} layer2 lacp
delete network interface ethernet {{member2}} aggregate-group
delete network interface ethernet {{member2}} layer2 lacp
delete network interface aggregate-ethernet {{ae_name}}
commit
# 复核
show interface all

entries.commands:
# ===== 静态路由（PAN-OS）=====
configure
set network virtual-router default routing-table ip static-route {{route_name}} destination {{dest_net}}/{{prefix_len}}
set network virtual-router default routing-table ip static-route {{route_name}} nexthop ip-address {{next_hop}}
set network virtual-router default routing-table ip static-route {{route_name}} interface {{out_interface}}
set network virtual-router default routing-table ip static-route {{route_name}} metric {{metric}}
set network virtual-router default routing-table ip static-route {{default_route_name}} destination 0.0.0.0/0
set network virtual-router default routing-table ip static-route {{default_route_name}} nexthop ip-address {{next_hop}}
set network virtual-router default routing-table ip static-route {{default_route_name}} interface {{out_interface}}
commit
show routing route
show routing route type static
test routing fib-lookup virtual-router default ip {{probe_ip}}

# ===== 地址对象 + 安全策略（PAN-OS）=====
configure
set address {{src_obj}} ip-netmask {{src_net}}/{{src_prefix}}
set address {{dst_obj}} ip-netmask {{dst_net}}/{{dst_prefix}}
set service {{svc_obj}} protocol tcp port {{dst_port}}
set rulebase security rules {{rule_name}} from {{src_zone}}
set rulebase security rules {{rule_name}} to {{dst_zone}}
set rulebase security rules {{rule_name}} source {{src_obj}}
set rulebase security rules {{rule_name}} destination {{dst_obj}}
set rulebase security rules {{rule_name}} application {{application}}
set rulebase security rules {{rule_name}} service {{svc_obj}}
set rulebase security rules {{rule_name}} action allow
set rulebase security rules {{rule_name}} log-end yes
commit
show rulebase security rules
show session all filter rule {{rule_name}}

entries.rollback:
# 回退：先删策略再删对象/服务（被引用时 delete 会被拒）
configure
delete rulebase security rules {{rule_name}}
delete address {{src_obj}}
delete address {{dst_obj}}
delete service {{svc_obj}}
commit
# 复核
show rulebase security rules

entries.commands:
# ===== 源 NAT + 目的 NAT（PAN-OS）=====
configure
! ---- 1) 源 NAT：内网出网做 PAT（借用出接口地址）----
set rulebase nat rules {{snat_name}} from {{src_zone}}
set rulebase nat rules {{snat_name}} to {{dst_zone}}
set rulebase nat rules {{snat_name}} source {{src_net}}/{{src_prefix}}
set rulebase nat rules {{snat_name}} destination any
set rulebase nat rules {{snat_name}} service any
set rulebase nat rules {{snat_name}} source-translation dynamic-ip-and-port interface-address interface {{out_interface}}
! ---- 2) 目的 NAT：公网端口映射到内网服务器 ----
set rulebase nat rules {{dnat_name}} from {{untrust_zone}}
set rulebase nat rules {{dnat_name}} to {{trust_zone}}
set rulebase nat rules {{dnat_name}} destination {{public_ip}}/32
set rulebase nat rules {{dnat_name}} service {{svc_name}}
set rulebase nat rules {{dnat_name}} source any
set rulebase nat rules {{dnat_name}} destination-translation translated-address {{inside_ip}}
set rulebase nat rules {{dnat_name}} destination-translation translated-port {{inside_port}}
commit
show running nat-policy
show session all

# ===== 修改管理员口令（PAN-OS）=====
configure
set mgt-config users {{username}} password
! ↑ 交互输入两次新口令，无法在脚本里自动化
set mgt-config password-complexity enabled yes
set mgt-config password-complexity minimum-length {{min_len}}
set mgt-config password-complexity minimum-numeric {{min_numeric}}
set mgt-config password-complexity minimum-special {{min_special}}
set mgt-config password-complexity password-history-count {{history}}
set mgt-config password-complexity password-change-period {{change_days}}
set mgt-config password-complexity password-change-warning {{warning_days}}
commit
show mgt-config password-complexity

# ===== SNMP 配置（PAN-OS）=====
configure
set deviceconfig system snmp-setting access-setting version v2c snmp-community-string {{ro_community}}
set deviceconfig system snmp-setting access-setting version v2c permitted-ip {{nms_ip}}/32
set deviceconfig system snmp-setting trap-setting v2c enable yes
set deviceconfig system snmp-setting trap-setting v2c servers {{nms_ip}}
set deviceconfig system snmp-setting trap-setting v2c community-string {{ro_community}}
commit
show deviceconfig system snmp-setting

entries.rollback:
# 回退：删除认证 profile 与 server-profile，管理员恢复本地认证
delete shared authentication-profile {{auth_profile}}
delete shared server-profile radius {{radius_profile}}
commit
# 管理员侧：Web 上把认证 profile 改回 None

entries.commands:
# ===== 1) 建区域（layer3 类型）=====
set zone {{zone_name}} network layer3 {{interface}}
# ===== 2) 接口先加入虚拟路由器（区域归属的前置条件）=====
set network virtual-router {{vr_name}} interface {{interface}}
# ===== 3) 提交 =====
commit description "{{commit_note}}"
# ===== 4) 复核 =====
show zone {{zone_name}}

entries.rollback:
# 回退：先解除策略/路由对区域的引用，再删区域（接口本身保留）
delete zone {{zone_name}}
# 若该接口是为本次变更临时加入 VR 的，可按需移除：
# delete network virtual-router {{vr_name}} interface {{interface}}
commit

entries.commands:
# ===== 1) 目的地址对象（公网 VIP）=====
set address {{vip_obj}} ip-netmask {{public_ip}}
# ===== 2) 入向放行规则（untrust → 服务所在区）=====
set rulebase security rules {{rule_name}} from {{src_zone}} to {{dst_zone}}
set rulebase security rules {{rule_name}} source any
set rulebase security rules {{rule_name}} destination {{vip_obj}}
set rulebase security rules {{rule_name}} application {{application}}
set rulebase security rules {{rule_name}} service {{service}}
set rulebase security rules {{rule_name}} action allow
set rulebase security rules {{rule_name}} profile-setting group {{profile_group}}
set rulebase security rules {{rule_name}} log-end yes
# ===== 3) 置于拒绝规则之前（规则从上到下首个命中即生效）=====
move rulebase security rules {{rule_name}} before {{before_rule}}
commit description "{{commit_note}}"
# ===== 4) 复核（预判命中 + 运行配置）=====
test security-policy-match from {{src_zone}} to {{dst_zone}} source {{test_src}} destination {{public_ip}} destination-port {{dst_port}} protocol 6
show running security-policy

entries.rollback:
# 回退：删入向规则与临时地址对象（公网发布立即中断）
delete rulebase security rules {{rule_name}}
# 地址对象若被 NAT/其他规则引用，先解除引用再删：
# delete address {{vip_obj}}
commit

entries.commands:
# ===== 1) 建服务对象（TCP）=====
set service {{svc_name}} protocol tcp port {{port}}
# UDP 服务：set service {{svc_name}} protocol udp port {{port}}
# ===== 2) 提交并复核 =====
commit description "{{commit_note}}"
show service

entries.rollback:
# 回退：先确认无策略引用，再删服务对象
delete service {{svc_name}}
commit

entries.commands:
# ===== 1) 按条件查会话（先看后清）=====
show session all filter source {{src_ip}} destination {{dst_ip}} destination-port {{dst_port}}
# ===== 2) 单条会话详情（含 NAT 前后地址与命中规则）=====
show session id {{session_id}}
# ===== 3) 强制清除（业务瞬断，终端重连即恢复）=====
clear session all filter source {{src_ip}} destination {{dst_ip}}
# 单条清除：clear session id {{session_id}}
# ===== 4) 复核（命中会话应为 0）=====
show session all filter source {{src_ip}} destination {{dst_ip}}

# ===== 1) 启用 HA（主备）=====
set deviceconfig high-availability enabled yes
set deviceconfig high-availability group group-id {{group_id}}
set deviceconfig high-availability group mode {{ha_mode}}
set deviceconfig high-availability group description "{{ha_desc}}"
# ===== 2) 控制链路 HA1（含备份口）=====
set deviceconfig high-availability interface ha1 port {{ha1_port}}
set deviceconfig high-availability interface ha1 ip-address {{local_ha1_ip}}
set deviceconfig high-availability interface ha1 netmask {{ha1_mask}}
set deviceconfig high-availability interface ha1 peer-ip-address {{peer_ha1_ip}}
set deviceconfig high-availability interface ha1 backup port {{ha1b_port}}
# ===== 3) 数据链路 HA2（会话同步走这里）=====
set deviceconfig high-availability interface ha2 port {{ha2_port}}
# ===== 4) 会话与配置同步 =====
set deviceconfig high-availability group session-synchronization enabled yes
set deviceconfig high-availability group configuration-synchronization enabled yes
commit description "{{commit_note}}"
# ===== 5) 主备倒换（仅在活动设备执行；对端随即接管）=====
# request high-availability state suspend
# 恢复：request high-availability state functional
# ===== 6) 复核 =====
show high-availability state
show high-availability state-synchronization

# ===== 1) 隧道接口与区域归属 =====
set network interface tunnel units {{tunnel_if}} ip {{tunnel_ip}}
set network interface tunnel units {{tunnel_if}} comment "{{tunnel_desc}}"
set zone {{vpn_zone}} network layer3 {{tunnel_if}}
set network virtual-router {{vr_name}} interface {{tunnel_if}}
# ===== 2) IKE / IPsec 加密配置 =====
set network ike crypto-profiles ike-crypto-profiles {{ike_profile}} encryption {{ike_enc}} hash sha256 dh-group {{dh_group}}
set network ike crypto-profiles ipsec-crypto-profiles {{ipsec_profile}} esp encryption {{ipsec_enc}} esp authentication sha256 dh-group {{dh_group}}
# ===== 3) IKE 网关（预共享密钥）=====
set network ike gateway {{gw_name}} authentication pre-shared-key key {{psk}}
set network ike gateway {{gw_name}} local-address interface {{out_interface}}
set network ike gateway {{gw_name}} peer-address ip {{peer_ip}}
set network ike gateway {{gw_name}} protocol ikev1 ike-crypto-profile {{ike_profile}}
set network ike gateway {{gw_name}} protocol-common nat-traversal enable yes
# ===== 4) IPsec 隧道（含 proxy-id 选择子）=====
set network tunnel ipsec {{tunnel_name}} auto-key ike-gateway {{gw_name}}
set network tunnel ipsec {{tunnel_name}} auto-key ipsec-crypto-profile {{ipsec_profile}}
set network tunnel ipsec {{tunnel_name}} tunnel-interface {{tunnel_if}}
set network tunnel ipsec {{tunnel_name}} auto-key proxy-id {{proxy_id}} local {{local_net}} remote {{remote_net}}
# ===== 5) 去对端网段的路由 =====
set network virtual-router {{vr_name}} routing-table ip static-route {{route_name}} destination {{remote_net}} interface {{tunnel_if}}
# ===== 6) 放行隧道流量（生产请把 any 收成地址对象）=====
set rulebase security rules {{rule_name}} from {{local_zone}} to {{vpn_zone}}
set rulebase security rules {{rule_name}} source any
set rulebase security rules {{rule_name}} destination any
set rulebase security rules {{rule_name}} application any
set rulebase security rules {{rule_name}} service any
set rulebase security rules {{rule_name}} action allow
commit description "{{commit_note}}"
# ===== 7) 复核（IKE SA / IPsec SA / 隧道流量计数）=====
show vpn ike-sa
show vpn ipsec-sa
show vpn flow

entries.rollback:
# 回退：删规则 → 删路由 → 删隧道 → 删网关 → 删隧道接口
delete rulebase security rules {{rule_name}}
delete network virtual-router {{vr_name}} routing-table ip static-route {{route_name}}
delete network tunnel ipsec {{tunnel_name}}
delete network ike gateway {{gw_name}}
delete network interface tunnel units {{tunnel_if}}
commit

entries.commands:
# ===== 1) 漏洞防护配置文件（按规则动作）=====
set profiles vulnerability {{vuln_profile}} rules {{vuln_rule}} action {{vuln_action}}
# ===== 2) 防病毒配置文件（http / smtp 解码器）=====
set profiles antivirus {{av_profile}} decoder http action {{av_action}}
set profiles antivirus {{av_profile}} decoder smtp action {{av_action}}
# ===== 3) 打成配置文件组（策略侧只引组，便于统一调整）=====
set profile-group {{pg_name}} virus {{av_profile}}
set profile-group {{pg_name}} vulnerability {{vuln_profile}}
# ===== 4) 绑定到策略 =====
# set rulebase security rules {{rule_name}} profile-setting group {{pg_name}}
commit description "{{commit_note}}"
# ===== 5) 复核 =====
show profiles vulnerability
show profiles antivirus

entries.rollback:
# 回退：先解除策略绑定，再删组与配置文件
set rulebase security rules {{rule_name}} profile-setting none
delete profile-group {{pg_name}}
delete profiles vulnerability {{vuln_profile}}
delete profiles antivirus {{av_profile}}
commit

entries.commands:
# ===== 1) 静态 IP 直配（layer3）=====
set network interface ethernet {{interface}} layer3 ip {{ip}}
set network interface ethernet {{interface}} layer3 mtu {{mtu}}
set network interface ethernet {{interface}} layer3 interface-management-profile {{mgmt_profile}}
set network interface ethernet {{interface}} comment "{{comment}}"
# ===== 2) 入虚拟路由器 + 划区域（直配后必须做，否则不转发）=====
